/* ===== Google Cloud Console — 100 native facets (data-spectrum="gcp"). Token-driven, self-contained. ===== */
.gcp-root{--gcp-radius:4px;--gcp-font:"Google Sans", Roboto, "Segoe UI", system-ui, -apple-system, sans-serif;font-family:var(--gcp-font,inherit)}
@keyframes gcpBtnPulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--_rgb),.5)}50%{box-shadow:0 0 0 6px rgba(var(--_rgb),0)}}
.gcp-btn{display:inline-flex;align-items:center;gap:8px;padding:9px 18px;border-radius:var(--gcp-radius,999px);background:var(--_c);color:#fff;font-weight:700;border:0;animation:gcpBtnPulse 2.4s ease-in-out infinite}
@keyframes gcpTgKnob{0%,100%{left:2px}50%{left:20px}}
.gcp-toggle{position:relative;width:44px;height:24px;border-radius:999px;background:rgba(var(--_rgb),.28);border:1px solid rgba(var(--_rgb),.5)}
.gcp-toggle::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.7);animation:gcpTgKnob 2.6s ease-in-out infinite}
@keyframes gcpChipShine{0%{background-position:-160% 0}60%,100%{background-position:260% 0}}
.gcp-chip{position:relative;overflow:hidden;display:inline-flex;align-items:center;padding:4px 12px;border-radius:999px;background:rgba(var(--_rgb),.16);border:1px solid rgba(var(--_rgb),.4);color:var(--_c);font-size:12px;font-weight:700}
.gcp-chip::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 40%,rgba(var(--_rgb),.4) 50%,transparent 60%);background-size:250% 100%;animation:gcpChipShine 3s linear infinite;pointer-events:none}
@keyframes gcpMenuSel{0%,100%{background:rgba(var(--_rgb),.12)}50%{background:rgba(var(--_rgb),.26)}}
.gcp-menu{min-width:150px;padding:6px;border-radius:var(--gcp-radius,12px);background:var(--panel2);border:1px solid var(--line)}
.gcp-menu .gcp-mi{padding:7px 10px;border-radius:8px;color:var(--ink);font-size:12px}
.gcp-menu .gcp-sel{color:var(--_c);animation:gcpMenuSel 2.8s ease-in-out infinite}
@keyframes gcpNotifIn{0%,100%{transform:translateX(-6px);opacity:.75}50%{transform:translateX(0);opacity:1}}
.gcp-toast{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);border-left:3px solid var(--_c);color:var(--ink);font-size:12px;animation:gcpNotifIn 3s ease-in-out infinite}
.gcp-toast::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.8)}
@keyframes gcpCalloutEdge{0%{transform:translateX(-120%)}100%{transform:translateX(120%)}}
.gcp-callout{position:relative;overflow:hidden;padding:10px 14px;border-radius:10px;background:rgba(var(--_rgb),.1);border:1px solid rgba(var(--_rgb),.35);color:var(--ink);font-size:12px}
.gcp-callout::after{content:"";position:absolute;top:0;left:0;height:2px;width:60%;background:linear-gradient(90deg,transparent,var(--_c),transparent);animation:gcpCalloutEdge 2.6s linear infinite;pointer-events:none}
@keyframes gcpBarGrow{0%{transform:scaleY(.25)}50%{transform:scaleY(1)}100%{transform:scaleY(.25)}}
.gcp-chart{display:flex;align-items:flex-end;gap:5px;height:44px;padding:6px 8px;border-radius:10px;background:var(--panel2);border:1px solid var(--line)}
.gcp-chart i{flex:1;background:var(--_c);border-radius:3px 3px 0 0;transform-origin:bottom;animation:gcpBarGrow 2.4s ease-in-out infinite}
.gcp-chart i:nth-child(2){animation-delay:.2s}.gcp-chart i:nth-child(3){animation-delay:.4s}.gcp-chart i:nth-child(4){animation-delay:.6s}
@keyframes gcpInputCaret{0%,49%{opacity:1}50%,100%{opacity:0}}
.gcp-field{display:inline-flex;align-items:center;gap:2px;min-width:150px;padding:8px 11px;border-radius:10px;background:var(--panel);border:1px solid var(--_c);box-shadow:0 0 0 3px rgba(var(--_rgb),.18);color:var(--ink);font-size:12px}
.gcp-field .gcp-caret{width:1.5px;height:14px;background:var(--_c);animation:gcpInputCaret 1.1s step-end infinite}
@keyframes gcpProg{0%{width:8%}80%,100%{width:96%}}
.gcp-prog{width:150px;height:8px;border-radius:999px;background:rgba(var(--_rgb),.18);overflow:hidden}
.gcp-prog i{display:block;height:100%;border-radius:inherit;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:gcpProg 3s ease-in-out infinite}
@keyframes gcpAvRing{to{transform:rotate(1turn)}}
.gcp-avatar{position:relative;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);color:var(--ink);font-weight:800}
.gcp-avatar::before{content:"";position:absolute;inset:-3px;border-radius:50%;background:conic-gradient(from 0deg,var(--_c),transparent 55%,var(--_c));-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));animation:gcpAvRing 3.4s linear infinite}
@keyframes gcpBadgePop{0%,100%{transform:scale(1)}30%{transform:scale(1.25)}}
.gcp-badge{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--_c);color:#fff;font-size:11px;font-weight:800;animation:gcpBadgePop 2s ease-in-out infinite}
@keyframes gcpTabSlide{0%,100%{left:2px}50%{left:calc(50% + 1px)}}
.gcp-tabs{position:relative;display:inline-flex;padding:3px;border-radius:999px;background:var(--panel2);border:1px solid var(--line)}
.gcp-tabs span{position:relative;z-index:1;padding:5px 14px;font-size:12px;color:var(--ink)}
.gcp-tabs::before{content:"";position:absolute;top:3px;bottom:3px;width:calc(50% - 3px);left:2px;border-radius:999px;background:rgba(var(--_rgb),.9);animation:gcpTabSlide 3.2s ease-in-out infinite}
@keyframes gcpTipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.gcp-tip{display:inline-block;padding:6px 10px;border-radius:8px;background:var(--panel2);border:1px solid var(--_c);color:var(--ink);font-size:11px;box-shadow:0 4px 14px rgba(var(--_rgb),.3);animation:gcpTipFloat 2.6s ease-in-out infinite}
@keyframes gcpSpin{to{transform:rotate(1turn)}}
.gcp-spinner{width:26px;height:26px;border-radius:50%;border:3px solid rgba(var(--_rgb),.22);border-top-color:var(--_c);animation:gcpSpin 1s linear infinite}
@keyframes gcpCardGlow{0%,100%{box-shadow:0 0 0 1px var(--line)}50%{box-shadow:0 0 16px rgba(var(--_rgb),.4)}}
.gcp-card{width:150px;padding:12px;border-radius:var(--gcp-radius,12px);background:var(--card);color:var(--ink);animation:gcpCardGlow 3.4s ease-in-out infinite}
.gcp-card b{color:var(--_c);font-size:12px}.gcp-card p{margin:4px 0 0;font-size:11px;color:var(--muted)}
@keyframes gcpCheckIn{0%,20%{clip-path:inset(0 100% 0 0)}60%,100%{clip-path:inset(0 0 0 0)}}
.gcp-check{position:relative;width:22px;height:22px;border-radius:6px;background:var(--_c);display:grid;place-items:center}
.gcp-check::after{content:"✓";color:#fff;font-size:14px;font-weight:900;animation:gcpCheckIn 2.4s ease-in-out infinite}
@keyframes gcpSliderThumb{0%,100%{left:2px}50%{left:calc(100% - 16px)}}
.gcp-slider{position:relative;width:150px;height:6px;border-radius:999px;background:rgba(var(--_rgb),.2)}
.gcp-slider::before{content:"";position:absolute;top:-5px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:gcpSliderThumb 3s ease-in-out infinite}
@media(prefers-reduced-motion:reduce){.gcp-root [class*="gcp-"],.gcp-root [class*="gcp-"]::before,.gcp-root [class*="gcp-"]::after,.gcp-root [class],.gcp-root [class]::before,.gcp-root [class]::after{animation:none!important}}

